// Normalizza Jira e GitHub nel payload di POST /ingest (vedi jarvis/ingest.py).
// Lo snapshot deve essere completo: se una sorgente è paginata o troncata, meglio fallire che chiudere task a torto.
const JIRA_BASE = 'https://REPLACE_WITH_JIRA_HOST.atlassian.net';
const MAX_DESCRIPTION = 8000;

function adfToText(node) {
  if (!node) return '';
  if (node.type === 'text') return node.text || '';
  const inner = (node.content || []).map(adfToText).join('');
  return ['paragraph', 'heading', 'listItem', 'codeBlock'].includes(node.type) ? inner + '\n' : inner;
}

function truncate(s) {
  return s && s.length > MAX_DESCRIPTION ? s.slice(0, MAX_DESCRIPTION) + '…' : s;
}

function projectStatus(issue) {
  for (const pi of issue.projectItems?.nodes || []) {
    for (const fv of pi.fieldValues?.nodes || []) {
      if (fv.field?.name === 'Status' && fv.name) return fv.name;
    }
  }
  return null;
}

const me = $('Jira - myself').first().json;
const jira = $('Jira - task').first().json;
if (jira.isLast === false || jira.nextPageToken) {
  throw new Error('Jira: risultati paginati, snapshot incompleto. Restringere la JQL o gestire la paginazione.');
}

const tasks = (jira.issues || []).map((issue) => ({
  source: 'jira',
  external_id: issue.key,
  container: issue.fields.project.key,
  title: issue.fields.summary,
  description: truncate(adfToText(issue.fields.description).trim()) || null,
  url: `${JIRA_BASE}/browse/${issue.key}`,
  source_status: issue.fields.status.name,
  labels: issue.fields.labels || [],
  created_by: issue.fields.reporter?.accountId || null,
  assignee: issue.fields.assignee?.accountId || null,
  issue_type: issue.fields.issuetype?.name || null,
}));

for (const node of ['GitHub - team', 'GitHub - personale']) {
  // Una pagina per item (paginazione del nodo HTTP).
  const pages = $(node).all().map((i) => i.json);
  const errors = pages.find((p) => p.errors);
  if (errors) throw new Error(`${node}: ${JSON.stringify(errors.errors)}`);
  const issues = pages.flatMap((p) => p.data.search.nodes);
  const issueCount = pages[0].data.search.issueCount;
  if (issueCount > issues.length) {
    throw new Error(`${node}: ${issueCount} issue ma solo ${issues.length} ricevute, snapshot incompleto.`);
  }
  for (const issue of issues) {
    const repo = issue.repository.nameWithOwner;
    tasks.push({
      source: 'github',
      external_id: `${repo}#${issue.number}`,
      container: repo,
      title: issue.title,
      description: truncate(issue.body) || null,
      url: issue.url,
      source_status: projectStatus(issue) || issue.state,
      labels: issue.labels.nodes.map((l) => l.name),
      created_by: issue.author?.login || null,
      assignee: issue.assignees.nodes[0]?.login || null,
    });
  }
}

return [{ json: { identities: { jira: me.accountId }, complete_sources: ['jira', 'github'], tasks } }];
